import re
from abc import ABC, abstractmethod

from .telnet import TelnetOpticalSwitch


class Hbte(TelnetOpticalSwitch, ABC):
    """
    | Base class for HBTE optical switches
    | Kwargs available in the interface:

    :param str model: Model of the optical switch
    :param str addr: Hostname or IP address of the optical switch
    :param int, optional port: Port number of the optical switch *(defaults to 5000)*
    :param int, optional timeout: Timeout for the optical switch *(defaults to 10)*
    """

    cr_lf = "*\r\n"

    def __init__(self, addr, port=5000, timeout=10):
        super().__init__(addr, port, timeout)

    @property
    @abstractmethod
    def check_code(self):
        pass

    @property
    @abstractmethod
    def set_prefix(self):
        pass

    def get_optical_switch_channels(self):
        """
        Get information about optical switch channels

        :raises Timeout(OpticalSwitchConnectionError): Request didn't succeed in the specified timeout.
        :raises OpticalSwitchConnectionError: Telnet connection closed unexpectedly.
        :return: Dictionary with input channel as key and output channel as value
        """
        cmd = self._build_telnet_get_command()
        self.telnet_client.write_cmd(cmd)
        response = self.telnet_client.collect_output()
        parsed_response = self._parse_get_response(response)
        return parsed_response

    def set_optical_switch_channels(self, new_settings):
        """
        Set optical switch channels settings

        :param dict new_settings: dictionary with module as key and channel as value
        :raises Timeout(OpticalSwitchConnectionError): Request didn't succeed in the specified timeout.
        :raises OpticalSwitchConnectionError: Telnet connection closed unexpectedly.
        :raises InvalidInput(OpticalSwitchError): Given module or channel is out of range.
        """
        cmd = self._build_telnet_set_command(new_settings)
        self.telnet_client.write_cmd(cmd)
        self._check_if_settings_changed(new_settings)

    def remove_all_connections(self):
        """
        Close all connections on the optical switch

        :raises OpticalSwitchConnectionError: Telnet connection closed unexpectedly.
        """
        for channel in range(1, self.channel_amount + 1):
            cmd_setting = "0" + str(channel) + "00"
            set_cmd = self.set_prefix + cmd_setting + self.cr_lf
            self.telnet_client.write_cmd(set_cmd.encode(self._encoding))

    def _build_telnet_get_command(self):
        return self.check_code.encode(self._encoding)

    def _build_telnet_set_command(self, new_setting):
        self._check_if_modules_and_channels_in_range(new_setting)
        cmd_setting = "0" + str(list(new_setting.keys())[0]) + "01"
        set_cmd = self.set_prefix + cmd_setting + self.cr_lf
        return set_cmd.encode(self._encoding)

    def _parse_get_response(self, resp):
        resp = re.findall(r"\d+", resp)[0]
        settings = self._get_settings_from_resp(resp)
        return settings

    def _get_settings_from_resp(self, resp):
        settings = {}
        resp = list(resp)
        for i in range(3, self.channel_amount * 4 + 1, 4):
            if resp[i] == "1":
                channel = int((i + 1) / 4)
                settings[channel] = channel
        return settings


class Hbte_D4_4(Hbte):
    def __init__(self, addr, **kwargs):
        super().__init__(addr, **kwargs)

    @property
    def check_code(self):
        return "$TA,D*\r\n"

    @property
    def set_prefix(self):
        return "$TA,D,"

    @property
    def channel_amount(self):
        return 4

    @property
    def module_amount(self):
        return 4
